// ─── Project 5 | Batch 1 — Error Handler ─────────────────────────────────
// Handles BOTH error schemas from n8n Error Trigger:
//   Schema A: item.execution (error in a regular workflow node)
//   Schema B: item.trigger   (error in the trigger node itself)
// Builds pre-sanitized Slack Block Kit JSON for dispatch.
// ─────────────────────────────────────────────────────────────────────────

const item = $input.first().json;

// ── Resolve error payload across both schemas ──
const workflow  = item?.workflow ?? {};
const exec      = item?.execution ?? null;
const trigger   = item?.trigger   ?? null;

const workflowName = workflow?.name ?? 'Unknown Workflow';
const workflowId   = workflow?.id   ?? 'Unknown';

let errorMessage, failedNode, executionId, executionUrl, mode, errorSchema;

if (exec) {
  // Schema A: normal execution error
  errorMessage  = exec.error?.message         ?? 'No error message provided';
  failedNode    = exec.lastNodeExecuted        ?? 'Unknown Node';
  executionId   = exec.id                     ?? 'N/A';
  executionUrl  = exec.url                    ?? '#';
  mode          = exec.mode                   ?? 'unknown';
  errorSchema   = 'execution';
} else if (trigger) {
  // Schema B: trigger-level failure (workflow never started)
  errorMessage  = trigger.error?.message      ?? 'Trigger failed';
  failedNode    = 'Trigger Node (workflow did not execute)';
  executionId   = 'N/A';
  executionUrl  = '#';
  mode          = trigger.mode                ?? 'trigger';
  errorSchema   = 'trigger';
} else {
  // Fallback: unknown error payload structure
  errorMessage  = 'Unknown error';
  failedNode    = 'Unknown';
  executionId   = 'N/A';
  executionUrl  = '#';
  mode          = 'unknown';
  errorSchema   = 'unknown';
}

// ── Sanitize executionUrl (F-06): only allow valid https:// URLs in Slack button ──
// Prevents javascript: URIs or other payloads from reaching the Slack actions block.
const safeUrl = (url) => {
  if (typeof url !== 'string' || !url.startsWith('https://')) return '#';
  try { new URL(url); return url; } catch { return '#'; }
};
executionUrl = safeUrl(executionUrl);

// ── Candidate name (populated via execution.customData in Batch 2+) ──
const candidateName = item?.execution?.customData?.candidate_name ?? 'N/A';

// ── Priority classification ──
// LOW  = transient infrastructure errors (5xx, rate limits, timeouts)
// HIGH = logic/config failures requiring human investigation
const transientPatterns = [
  /\b503\b/, /\b500\b/, /\b429\b/,
  /rate.?limit/i, /too.?many.?requests/i, /service.?unavailable/i,
  /timeout/i,    /timed.?out/i,           /temporarily.?unavailable/i,
  /ECONNRESET/i, /ETIMEDOUT/i,            /ENOTFOUND/i,
  /bad.?gateway/i, /gateway.?timeout/i
];
const isTransient   = transientPatterns.some(p => p.test(errorMessage));
const priority      = isTransient ? 'LOW' : 'HIGH';
const priorityEmoji = priority === 'HIGH' ? '❗' : '⚠️';

// ── Safe string helper ──
// Collapses newlines/tabs, trims, caps at 500 chars
const safe = (val, fallback = 'N/A') =>
  String(val ?? fallback)
    .replace(/\r?\n/g, ' ')
    .replace(/\t/g, ' ')
    .trim()
    .substring(0, 500);

const sWorkflowName  = safe(workflowName);
const sFailedNode    = safe(failedNode);
const sErrorMessage  = safe(errorMessage);
const sExecutionId   = safe(executionId);
const sCandidateName = safe(candidateName);
const timestamp      = new Date().toISOString();

// ── Slack fallback text (mobile notification preview) ──
const slackFallback = `${priorityEmoji} [${priority}] Error in "${sWorkflowName}" at "${sFailedNode}" — ${sErrorMessage}`;

// ── Slack Block Kit blocks ──
const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: `${priorityEmoji}  [${priority}] Workflow Error — Recruitment Pipeline`, emoji: true }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Workflow*\n${sWorkflowName}` },
      { type: 'mrkdwn', text: `*Failed At*\n\`${sFailedNode}\`` }
    ]
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: `*Error Message*\n\`\`\`${sErrorMessage}\`\`\`` }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Priority*\n${priorityEmoji} ${priority}` },
      { type: 'mrkdwn', text: `*Candidate*\n${sCandidateName}` }
    ]
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '↗ View Execution', emoji: false },
        url: executionUrl,
        style: 'danger'
      }
    ]
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: `Execution \`${sExecutionId}\`  •  Schema: ${errorSchema}  •  ${timestamp}` }
    ]
  },
  { type: 'divider' }
];

return [{
  json: {
    workflowName:  sWorkflowName,
    executionId:   sExecutionId,
    executionUrl,
    errorMessage:  sErrorMessage,
    failedNode:    sFailedNode,
    candidateName: sCandidateName,
    priority,
    errorSchema,
    mode,
    timestamp,
    slackFallback,
    slackBlocks: JSON.stringify(blocks)
  }
}];
